package lesson

import (
	"net/http"

	"github.com/gin-gonic/gin"
)

type createUser struct {
	Name string `json:"name" binding:"required"`
	Age  int    `json:"age" binding:"required,min=1,max=130"`
}

func Router() http.Handler {
	gin.SetMode(gin.TestMode)
	router := gin.New()
	router.POST("/users", func(c *gin.Context) {
		var input createUser
		if err := c.ShouldBindJSON(&input); err != nil {
			c.JSON(400, gin.H{"code": "invalid_user"})
			return
		}
		c.JSON(http.StatusCreated, gin.H{"name": input.Name})
	})
	return router
}
```

**users_test.go**

```go
package lesson

import (
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
)

func TestBinding(t *testing.T) {
	for _, test := range []struct {
		body string
		want int
	}{{`{"name":"Ada","age":36}`, 201}, {`{"name":"","age":36}`, 400}, {`{"name":"Ada"`, 400}} {
		recorder := httptest.NewRecorder()
		request := httptest.NewRequest(http.MethodPost, "/users", strings.NewReader(test.body))
		request.Header.Set("Content-Type", "application/json")
		Router().ServeHTTP(recorder, request)
		if recorder.Code != test.want {
			t.Fatalf("body=%s status=%d", test.body, recorder.Code)
		}
	}
}
```

**Run it**

```bash
go test -race ./...
go vet ./...
```

Every test sets the JSON media type because Gin chooses binders using request information; malformed and invalid bodies keep one JSON response path.
